SELECT DISTINCT parent.chembl_id AS compound_chembl_id, cs.canonical_smiles, cr.compound_key, COALESCE(CAST(d.pubmed_id AS TEXT), d.doi) AS pubmed_id_or_doi, a.description AS assay_description, act.standard_type, act.standard_relation, act.standard_value, act.standard_units, act.activity_comment, td.chembl_id AS target_chembl_id, td.pref_name AS target_name, td.organism AS target_organism FROM molecule_dictionary parent LEFT JOIN molecule_hierarchy mh ON mh.parent_molregno = parent.molregno LEFT JOIN molecule_dictionary child ON child.molregno = mh.molregno CROSS JOIN molecule_dictionary base JOIN compound_records cr_base ON base.molregno = cr_base.molregno JOIN activities act ON cr_base.record_id = act.record_id JOIN assays a ON act.assay_id = a.assay_id JOIN target_dictionary td ON act.tid = td.tid JOIN compound_records cr ON act.record_id = cr.record_id JOIN docs d ON cr.doc_id = d.doc_id JOIN compound_structures cs ON cr.molregno = cs.molregno WHERE parent.chembl_id = 'CHEMBL493620' AND td.chembl_id = 'CHEMBL612557' AND act.standard_type = 'IC50' AND (cr.molregno = parent.molregno OR cr.molregno = child.molregno) ORDER BY parent.chembl_id, cs.canonical_smiles, cr.compound_key, COALESCE(CAST(d.pubmed_id AS TEXT), d.doi), a.description, act.standard_type, act.standard_relation, act.standard_value, act.standard_units, act.activity_comment, td.chembl_id, td.pref_name, td.organism
